begin;
do $$
declare u uuid:=gen_random_uuid();seller uuid:=gen_random_uuid();blank uuid;dtf uuid;pv uuid;pb uuid;mid uuid;receipt uuid:=gen_random_uuid();work uuid:=gen_random_uuid();cancelwork uuid:=gen_random_uuid();sale uuid:=gen_random_uuid();res uuid:=gen_random_uuid();rescancel uuid:=gen_random_uuid();pay uuid:=gen_random_uuid();ret uuid:=gen_random_uuid();item uuid;j jsonb;q int;n numeric;blocked boolean;result uuid;
begin
 insert into auth.users(id,email) values(u,u::text||'@example.invalid'),(seller,seller::text||'@example.invalid');
 update arma_private.user_security set requires_password_change=false where user_id in(u,seller);
 insert into public.user_roles(user_id,role_id) select u,id from public.roles where code='admin';insert into public.user_roles(user_id,role_id) select seller,id from public.roles where code='seller';
 delete from public.role_permissions where role_id=(select id from public.roles where code='admin') and permission_id=(select id from public.permissions where key='commerce.read_all');
 select v.id into blank from public.material_variants v join public.materials m on m.id=v.material_id where m.material_type='blank_shirt' limit 1;
 select v.id into dtf from public.material_variants v join public.materials m on m.id=v.material_id where m.material_type='dtf_transfer' limit 1;
 select v.id,b.id into pv,pb from public.product_variants v join public.inventory_balances b on b.product_variant_id=v.id where upper(v.size) in('S','M','L') limit 1;
 update public.inventory_balances set physical_quantity=10,reserved_quantity=0,average_unit_cost=100 where material_variant_id=blank;
 update public.inventory_balances set physical_quantity=100,reserved_quantity=0,average_unit_cost=20 where material_variant_id=dtf;
 update public.inventory_balances set physical_quantity=0,reserved_quantity=0,average_unit_cost=null where id=pb;
 execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 perform public.workshop_write('receive',jsonb_build_object('request_id',receipt,'variant_id',blank,'quantity',5,'unit_cost',200));
 perform public.workshop_write('receive',jsonb_build_object('request_id',receipt,'variant_id',blank,'quantity',5,'unit_cost',200));
 j:=public.workshop_options('material','',blank);if (j->0->>'available')::int<>15 or abs((j->0->>'cost')::numeric-133.3333)>.0001 then raise exception 'weighted cost or receipt idempotency failed: %',j;end if;
 perform public.workshop_write('recipe',jsonb_build_object('request_id',gen_random_uuid(),'variant_id',pv,'labor_cost',30,'target_margin',40,'lines',jsonb_build_array(jsonb_build_object('material_variant_id',blank,'quantity',1),jsonb_build_object('material_variant_id',dtf,'quantity',2))));
 perform public.workshop_write('start',jsonb_build_object('request_id',work,'variant_id',pv,'quantity',5));
 perform public.workshop_write('start',jsonb_build_object('request_id',work,'variant_id',pv,'quantity',5));
 j:=public.workshop_options('material','',blank);if (j->0->>'available')::int<>10 then raise exception 'start not reserved exactly once';end if;
 blocked:=false;begin perform public.workshop_write('finish',jsonb_build_object('request_id',gen_random_uuid(),'order_id',work,'quantity',6));exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'overproduction allowed';end if;
 perform public.workshop_write('finish',jsonb_build_object('request_id',gen_random_uuid(),'order_id',work,'quantity',3));
 perform public.workshop_write('finish',jsonb_build_object('request_id',gen_random_uuid(),'order_id',work,'quantity',3));
 j:=public.workshop_options('material','',blank);if (j->0->>'available')::int<>12 then raise exception 'unused blank not released';end if;
 j:=public.workshop_options('material','',dtf);if (j->0->>'available')::int<>94 then raise exception 'DTF actual consumption failed';end if;
 j:=public.workshop_options('product','',pv);if (j->0->>'available')::int<>3 or abs((j->0->>'cost')::numeric-203.3333)>.0001 then raise exception 'finished stock cost wrong: %',j;end if;
 perform public.workshop_write('start',jsonb_build_object('request_id',cancelwork,'variant_id',pv,'quantity',2));
 perform public.workshop_write('cancel',jsonb_build_object('request_id',gen_random_uuid(),'order_id',cancelwork));
 j:=public.workshop_options('material','',blank);if (j->0->>'available')::int<>12 then raise exception 'cancel did not release stock';end if;
 perform public.create_commerce_order(jsonb_build_object('request_id',sale,'kind','sale','variant_id',pv,'quantity',1,'unit_price',300,'payment_method','cash'));
 j:=public.commerce_history(sale);if (j->'payments'->0->>'amount')::numeric<>300 then raise exception 'sale receipt missing';end if;
 execute 'reset role';select id into item from public.commerce_order_items where order_id=sale;select unit_cost into n from public.commerce_order_items where id=item;if abs(n-203.3333)>.0001 then raise exception 'sale cost not captured';end if;
 execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 perform public.commerce_adjust('return',jsonb_build_object('request_id',ret,'order_id',sale,'item_id',item,'quantity',1,'amount',200,'method','card','restock',true,'reason','TEST RETURN'));
 perform public.commerce_adjust('return',jsonb_build_object('request_id',ret,'order_id',sale,'item_id',item,'quantity',1,'amount',200,'method','card','restock',true,'reason','TEST RETURN'));
 blocked:=false;begin perform public.commerce_adjust('return',jsonb_build_object('request_id',gen_random_uuid(),'order_id',sale,'item_id',item,'quantity',1,'amount',100,'method','cash','restock',true,'reason','TEST excess'));exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'excess returns allowed';end if;
 perform public.create_commerce_order(jsonb_build_object('request_id',res,'kind','reservation','variant_id',pv,'quantity',1,'unit_price',300,'deposit',50,'customer_name','TEST PAYMENTS','payment_method','cash'));
 perform public.commerce_adjust('payment',jsonb_build_object('request_id',pay,'order_id',res,'amount',100,'method','transfer'));
 perform public.commerce_adjust('payment',jsonb_build_object('request_id',pay,'order_id',res,'amount',100,'method','transfer'));
 blocked:=false;begin perform public.commerce_adjust('payment',jsonb_build_object('request_id',gen_random_uuid(),'order_id',res,'amount',151,'method','cash'));exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'overpayment allowed';end if;
 result:=public.resolve_reservation(res,'complete',gen_random_uuid(),'card',false);
 j:=public.business_dashboard(current_date-1,current_date+1);if (j->>'receipts')::numeric<>600 or (j->>'refunds')::numeric<>200 or (j->>'net_receipts')::numeric<>400 or (j->>'sale_count')::int<>2 then raise exception 'dashboard double counted payments: %',j;end if;
 perform public.create_commerce_order(jsonb_build_object('request_id',rescancel,'kind','reservation','variant_id',pv,'quantity',1,'unit_price',300,'deposit',50,'customer_name','TEST CANCEL','payment_method','cash'));
 perform public.commerce_adjust('payment',jsonb_build_object('request_id',gen_random_uuid(),'order_id',rescancel,'amount',100,'method','transfer'));
 perform public.resolve_reservation(rescancel,'cancel',gen_random_uuid(),'cash',true);
 j:=public.commerce_history(rescancel);select sum((x->>'amount')::numeric) into n from jsonb_array_elements(j->'payments')x;if n<>0 or jsonb_array_length(j->'payments')<>4 then raise exception 'cancellation did not refund original methods: %',j;end if;
 -- Seller cannot receive stock, read another seller's records, return without permission, or fetch costs.
 perform set_config('request.jwt.claims',jsonb_build_object('sub',seller,'role','authenticated')::text,true);
 blocked:=false;begin perform public.workshop_write('receive',jsonb_build_object('request_id',gen_random_uuid(),'variant_id',blank,'quantity',1,'unit_cost',1));exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'seller stock write allowed';end if;
 blocked:=false;begin perform public.commerce_adjust('payment',jsonb_build_object('request_id',gen_random_uuid(),'order_id',res,'amount',1,'method','cash'));exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'foreign payment allowed';end if;
 blocked:=false;begin perform public.commerce_history(sale);exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'foreign history allowed';end if;
 blocked:=false;begin execute 'select average_unit_cost from public.inventory_balances limit 1';exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'cost column exposed';end if;
 blocked:=false;begin execute 'select unit_cost from public.commerce_order_items limit 1';exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'sale cost exposed';end if;
 j:=public.business_dashboard(current_date-1,current_date+1);if (j->>'sales')::numeric<>0 or (j->>'finance')::boolean or jsonb_array_length(j->'prices')<>0 then raise exception 'seller dashboard leaks';end if;
 raise notice 'PASS: receipts, weighted costs, recipe, stock reservation, partial completion, cancellation, sale costs, idempotent returns, mixed payments, dashboard scope, cost protection';
end $$;
rollback;
